  .argv(i => ['renew-cert', i.domain])
  .on(opsOne, opsTwo)
  .recovery('rerun');

const pageOnCall = H.command('page-on-call')
  .input(z.object({ title: z.string() }))
  .argv(i => ['page', '--rotation', 'platform', '--summary', i.title])
  .on(local)
  .recovery('park');
