        H.ops.readWork,
        H.ops.writeWork,
        H.ops.resolve(approval, H.halts.changed, H.halts.interrupted),
        H.ops.readTelemetry,
      ],
    })
  )
  .observers(markdown.board('/srv/release/BOARD.md'));

