      const record = metrics.rate({
        among: { entry: 'halt', halt: counsel, status: 'resolved', resolver: 'human', facets: [categoryFacet.value(about.category)] },
        count: {
          entry: 'halt',
          halt: counsel,
          status: 'resolved',
          resolver: 'human',
          facets: [categoryFacet.value(about.category)],
          decision: { action: 'approve' },
