export const contractsHarness = H.harness('contracts')
  .ledger(sqlite.ledger('/srv/contracts/ledger.sqlite'))
  .lanes(contractsEu, contractsUs)
  .pools(H.pool('contracts-pool', [{ account: apiAccount, share: 1 }]))
