    control({ port: 7490, token: H.env('SUPPORT_CONTROL_TOKEN'), grants: [H.ops.readWork, H.ops.readTelemetry] })
  )
  .observers(board('/srv/support/BOARD.md'), telemetry('/srv/support/TELEMETRY.md'));

