      of: { entry: 'firing', trigger: approvalAudit, status: 'tripped', facets: [category.of(input.category)] },
      since,
    });
    const paused = metrics.sum({ of: 'durationMs', among: { entry: 'lane', lane: conversations, status: 'resumed' }, since });
