const evalRun = H.kind('eval-run')
  .data(z.object({ model: z.string(), suite: z.string(), summary: z.string().optional() }))
  .states(H.state('queued', 'pending'), H.state('scored', 'terminal', 'success'), H.state('eval-failed', 'terminal', 'failure'));

